export const ym3438_mode_ym2612 = 0x01;   /* Enables YM2612 emulation (MD1, MD2 VA2) */
export const ym3438_mode_readmode = 0x02; /* Enables status read on any port (TeraDrive, MD1 VA7, MD2, etc) */

const eg_num_attack = 0, eg_num_decay = 1, eg_num_sustain = 2, eg_num_release = 3;

// (cycles + k) % 24 and % 12 / % 6 lookups
const MOD24 = (k) => { const t = new Uint8Array(24); for (let i = 0; i < 24; i++) t[i] = (i + k) % 24; return t; };
const NEXT24 = MOD24(1), NCH = new Uint8Array(24), MOD6 = new Uint8Array(24), MOD12 = new Uint8Array(24), DIV6 = new Uint8Array(24);
for (let i = 0; i < 24; i++) { MOD6[i] = i % 6; MOD12[i] = i % 12; DIV6[i] = (i / 6) | 0; NCH[i] = (i % 6 + 1) % 6; }
// envelope-to-linear transform: ((exprom[(level & 0xff) ^ 0xff] | 0x400) << 2) >> (level >> 8), for level 0..0x1fff
const EXPT = new Int16Array(0x2000);
for (let l = 0; l < 0x2000; l++) EXPT[l] = ((exprom[(l & 0xff) ^ 0xff] | 0x400) << 2) >> (l >> 8);
// signed detune for (kcode << 3) | dt, exactly as PhaseCalcIncrement derives it
const DTT = new Int8Array(256);
for (let kc = 0; kc < 32; kc++) for (let d = 0; d < 8; d++) {
  const dt_l = d & 3; let det = 0;
  if (dt_l) { const k = kc > 0x1c ? 0x1c : kc; const sum = (k >> 2) + 9 + ((dt_l === 3 ? 1 : 0) | (dt_l & 2)); det = pg_detune[((sum & 1) << 2) | (k & 3)] >> (9 - (sum >> 1)); }
  DTT[(kc << 3) | d] = d & 4 ? -det : det;
}
const EG_STEPHI = new Uint8Array([0, 0, 0, 0, 1, 0, 0, 0, 1, 0, 1, 0, 1, 1, 1, 0]);
